// frontend/src/pages/Evenements.jsx
import React, { useState } from 'react'
import ProcessInfo              from '../components/ProcessInfo'
import EntreeInventaires        from '../components/EntreeInventaires'
import EntreeInventairesForm    from '../components/EntreeInventairesForm'
import StockViewer              from '../components/StockViewer'

export default function Evenements() {
  const [step, setStep] = useState('form')

  return (
    <div className="min-h-screen bg-white text-gray-800 flex flex-col">
      {/* Onglets */}
      <div className="container mx-auto flex justify-center space-x-8 py-6 border-b border-gray-200">
        {['process', 'inventaire', 'form'].map(tab => {
          const labels = { process: 'Process', inventaire: 'Inventaire', form: 'Formulaire' }
          return (
            <button
              key={tab}
              onClick={() => setStep(tab)}
              className={`
                text-sm font-medium
                ${step === tab ? 'text-green-600' : 'text-gray-500 hover:text-green-600'}
                transition
              `}
            >
              {labels[tab]}
            </button>
          )
        })}
      </div>

      {/* Contenu */}
      <main className="flex-1 container mx-auto px-4 py-8 space-y-8">
        {step === 'process' && (
          <div className="bg-white border border-gray-200 rounded-2xl shadow-sm p-6">
            <ProcessInfo />
          </div>
        )}

        {step === 'inventaire' && (
          <div className="bg-white border border-gray-200 rounded-2xl shadow-sm p-6">
            <EntreeInventaires />
          </div>
        )}

        {step === 'form' && (
          <div className="space-y-8">
            <div className="bg-white border border-gray-200 rounded-2xl shadow-sm p-6">
              <EntreeInventairesForm />
            </div>
            <div className="bg-white border border-gray-200 rounded-2xl shadow-sm p-6">
              <StockViewer />
            </div>
          </div>
        )}
      </main>
    </div>
)
}
